import{_ as l,b as t,c as a,g as o}from"./chunks/framework.86O3EbG5.js";const h=JSON.parse('{"title":"概率模型学习","description":"","frontmatter":{"title":"概率模型学习","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach/20.md","filePath":"articles/ai/books/ai-modern-approach/20.md"}'),r={name:"articles/ai/books/ai-modern-approach/20.md"};function e(n,i,s,d,_,c){return t(),a("div",null,[...i[0]||(i[0]=[o('<p>第 20 章关注如何从数据中学习概率模型，包括参数估计、隐变量模型和结构学习。核心内容包括：</p><h2 id="参数学习" tabindex="-1">参数学习</h2><ul><li><strong>最大似然估计（MLE）</strong>：选择使观测数据概率最大的参数</li><li><strong>最大后验估计（MAP）</strong>：结合先验分布，在数据量小时更稳健</li><li><strong>Dirichlet 先验</strong>：用于离散概率参数的共轭先验</li><li><strong>Beta 分布</strong>：二值变量的共轭先验</li></ul><h2 id="贝叶斯网络参数学习" tabindex="-1">贝叶斯网络参数学习</h2><ul><li>给定网络结构，从完整数据估计 CPT 参数</li><li>处理缺失数据时需要 EM 算法</li></ul><h2 id="期望最大化-em-算法" tabindex="-1">期望最大化（EM）算法</h2><ul><li><strong>E 步</strong>：计算隐变量的后验概率（期望）</li><li><strong>M 步</strong>：用期望计数更新参数</li><li>保证收敛到局部最优，但不保证全局最优</li></ul><h2 id="高斯混合模型-gmm" tabindex="-1">高斯混合模型（GMM）</h2><ul><li>用多个高斯分布的加权和建模数据</li><li>EM 算法估计混合系数、均值和方差</li><li>每个数据点属于各分量的后验概率在 E 步计算</li></ul><h2 id="结构学习" tabindex="-1">结构学习</h2><ul><li><strong>评分函数</strong>：BIC = ln P(D|G,θ̂) - d/2 ln N，平衡拟合度与模型复杂度</li><li><strong>搜索方法</strong>：K2 算法等贪心搜索</li><li>先验知识约束（如因果方向）可嵌入结构学习</li><li>学习得到的网络不一定代表因果结构</li></ul><h2 id="模型选择" tabindex="-1">模型选择</h2><ul><li>避免过拟合：BIC、交叉验证、信息准则</li><li>隐类数量选择：比较不同复杂度模型的 BIC 分数</li></ul>',13)])])}const p=l(r,[["render",e]]);export{h as __pageData,p as default};
